const input = $input.first().json;

const data = String(
  input.data ??
  input.callback_query?.data ??
  ''
).trim();

if (!data) {
  throw new Error('لم تصل callback data من Telegram');
}

const match = /^(approve|reject)_payment_(\d+)$/.exec(data);

if (!match) {
  throw new Error(`Callback غير معروف: ${data}`);
}

const action = match[1];
const paymentId = Number(match[2]);

return [
  {
    json: {
      action,
      payment_id: paymentId,
      callback_data: data,
    },
  },
];

