parameters.jsCode:
const src = $('Telegram Trigger').first().json;

const callback = src.callback_query;

const chatId =
  callback?.message?.chat?.id ??
  src.message?.chat?.id ??
  src.chat?.id;

const messageId =
  callback?.message?.message_id ??
  src.message?.message_id ??
  src.message_id;

if (!chatId) {
  throw new Error('لم يتم العثور على chat_id في Telegram Trigger');
}

if (!messageId) {
  throw new Error('لم يتم العثور على message_id في Telegram Trigger');
}

return [
  {
    json: {
      chat_id: chatId,
      message_id: Number(messageId),
      payment_id: Number(
        String(src.data ?? callback?.data ?? '')
          .split('_')
          .pop()
      ),
    },
  },
];

const db = $input.first().json;
const telegram = $('Prepare Telegram Edit').first().json;

const isApproved = db.payment_status === 'Approved';
const isClinic = db.invoice_type === 'Clinic';

const title = isApproved
  ? '✅ تم اعتماد طلب الدفع'
  : '❌ تم رفض طلب الدفع';

const paymentLabel = isApproved ? 'Approved' : 'Rejected';
const invoiceLabel = db.invoice_status || (isApproved ? 'Paid' : 'Pending');

const queueLine = (isApproved && isClinic && db.queue_number != null)
  ? `🎟️ رقم الدور: ${db.queue_number}\n`
  : '';

return [
  {
    json: {
      chat_id: Number(telegram.chat_id),
      message_id: Number(telegram.message_id),

      caption:
        `${title}\n\n` +
        `💰 طلب دفع\n\n` +
        `👤 المريض: ${db.patient_name || '-'}\n` +
        `🆔 رقم الهوية: ${db.national_id || '-'}\n` +
        `🧾 رقم الفاتورة: ${db.invoice_number || '-'}\n` +
        `📌 نوع الفاتورة: ${db.invoice_type || '-'}\n` +
        `${isClinic ? `🏥 العيادة: ${db.clinic_name || '-'}\n` : ''}` +
        `${isClinic ? `👨‍⚕️ الطبيب: ${db.doctor_name || '-'}\n` : ''}` +
        `${queueLine}` +
        `📝 الوصف: ${db.description || '-'}\n` +
        `💵 المبلغ: ${db.paid_amount ?? '-'}\n` +
        `🏦 اسم حساب المُرسل: ${db.sender_name || '-'}\n` +
        `📱 هاتف المُرسل: ${db.sender_phone || '-'}\n\n` +
        `💳 حالة الدفع: ${paymentLabel}\n` +
        `🧾 حالة الفاتورة: ${invoiceLabel}\n` +
        `📦 حالة التسليم: ${db.fulfillment_status || 'Pending'}`
    }
  }
];

